(1501, 'Exodus 1:18', 'Exodus', 1, 18, '&nbsp;نو بادشاه دايڼې راوغوښتلې او د هغوئ نه يې تپوس وکړو، ”تاسو ولې داسې کوئ؟ تاسو نران بچى ولې ژوندى پرېږدئ؟“', NULL, '&nbsp;نو بادشاه دايڼې راوغوښتلې او د هغوئ نه يې تپوس وکړو، ”تاسو ولې داسې کوئ؟ تاسو نران بچى ولې ژوندى پرېږدئ؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1502, 'Exodus 1:19', 'Exodus', 1, 19, '&nbsp;هغوئ هغۀ ته ووئيل، ”عبرانۍ ښځې د مِصريانو ښځو په شان نۀ دى، د دوئ په آسانۍ سره بچى پېدا کيږى او هلته زمونږ د رسېدو نه مخکښې د دوئ ماشومان پېدا شى.“', NULL, '&nbsp;هغوئ هغۀ ته ووئيل، ”عبرانۍ ښځې د مِصريانو ښځو په شان نۀ دى، د دوئ په آسانۍ سره بچى پېدا کيږى او هلته زمونږ د رسېدو نه مخکښې د دوئ ماشومان پېدا شى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1503, 'Exodus 1:22', 'Exodus', 1, 22, '&nbsp;په آخر کښې فِرعون خپلو ټولو خلقو له حُکم ورکړو چې، ”د عبرانيانو هر يو پېدا شوے بچے راوړئ او د نيل درياب کښې يې وغورزوئ، خو جينکۍ به ژوندۍ پرېږدئ.“', NULL, '&nbsp;په آخر کښې فِرعون خپلو ټولو خلقو له حُکم ورکړو چې، ”د عبرانيانو هر يو پېدا شوے بچے راوړئ او د نيل درياب کښې يې وغورزوئ، خو جينکۍ به ژوندۍ پرېږدئ.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1504, 'Exodus 2:1', 'Exodus', 2, 1, '&nbsp;په دې دوران کښې د ليوى قبيلې يو سړى په خپله قبيله کښې يوه ښځه وکړه،', NULL, '&nbsp;په دې دوران کښې د ليوى قبيلې يو سړى په خپله قبيله کښې يوه ښځه وکړه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1505, 'Exodus 2:2', 'Exodus', 2, 2, '&nbsp;او د هغې نه د هغۀ يو زوئ وشو. هغې وليدل چې دا ښۀ ښکلے ماشوم وو، نو هغې دا درې مياشتې پټ وساتلو.', NULL, '&nbsp;او د هغې نه د هغۀ يو زوئ وشو. هغې وليدل چې دا ښۀ ښکلے ماشوم وو، نو هغې دا درې مياشتې پټ وساتلو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1506, 'Exodus 2:3', 'Exodus', 2, 3, '&nbsp;خو چې کله هغې دا نور نۀ شو پټولے، هغې د لوخو نه جوړه شوې يوه ټوکرۍ راواخستله او په دې يې تارکول ولګول چې اوبۀ په کښې دننه نۀ ځى. هغې ماشوم په دې کښې کښېنولو او دا يې بيا د درياب په غاړه په لوخو کښې کېښوده.', NULL, '&nbsp;خو چې کله هغې دا نور نۀ شو پټولے، هغې د لوخو نه جوړه شوې يوه ټوکرۍ راواخستله او په دې يې تارکول ولګول چې اوبۀ په کښې دننه نۀ ځى. هغې ماشوم په دې کښې کښېنولو او دا يې بيا د درياب په غاړه په لوخو کښې کېښوده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1507, 'Exodus 2:4', 'Exodus', 2, 4, '&nbsp;د ماشوم خور لږه لرې ولاړه وه او کتل يې چې په هغۀ به څۀ کيږى.', NULL, '&nbsp;د ماشوم خور لږه لرې ولاړه وه او کتل يې چې په هغۀ به څۀ کيږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1508, 'Exodus 2:5', 'Exodus', 2, 5, '&nbsp;د فِرعون لور لامبلو له د درياب غاړې له راغله، د هغې خِدمتګارې هم د درياب په غاړه روانې وې نو ناڅاپه هغې په لوخو کښې هغه ټوکرۍ وليدله او يوه خِدمتګاره يې ورولېږله چې هغې ته يې را وړى.', NULL, '&nbsp;د فِرعون لور لامبلو له د درياب غاړې له راغله، د هغې خِدمتګارې هم د درياب په غاړه روانې وې نو ناڅاپه هغې په لوخو کښې هغه ټوکرۍ وليدله او يوه خِدمتګاره يې ورولېږله چې هغې ته يې را وړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1509, 'Exodus 2:6', 'Exodus', 2, 6, '&nbsp;د فِرعون لور ټوکرۍ کولاو کړه او يو ماشوم يې په کښې وليدو. هغۀ ژړل او د هغې ورباندې زړۀ وسوزېدلو. هغې ووئيل، ”دا ماشوم عبرانے دے.“', NULL, '&nbsp;د فِرعون لور ټوکرۍ کولاو کړه او يو ماشوم يې په کښې وليدو. هغۀ ژړل او د هغې ورباندې زړۀ وسوزېدلو. هغې ووئيل، ”دا ماشوم عبرانے دے.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1510, 'Exodus 2:7', 'Exodus', 2, 7, '&nbsp;بيا د هغۀ خور د فِرعون د لور نه تپوس وکړو، ”زۀ يو عبرانۍ ښځه راوغواړم څۀ چې دې ماشوم له سينه ورکوى؟“', NULL, '&nbsp;بيا د هغۀ خور د فِرعون د لور نه تپوس وکړو، ”زۀ يو عبرانۍ ښځه راوغواړم څۀ چې دې ماشوم له سينه ورکوى؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1511, 'Exodus 2:8', 'Exodus', 2, 8, '&nbsp;هغې ورته ووئيل، ”آو، لاړه شه.“ نو هغه جينۍ لاړه او د ماشوم خپله مور يې راوستله.', NULL, '&nbsp;هغې ورته ووئيل، ”آو، لاړه شه.“ نو هغه جينۍ لاړه او د ماشوم خپله مور يې راوستله.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1512, 'Exodus 2:9', 'Exodus', 2, 9, '&nbsp;شهزادګۍ دې ښځې ته ووئيل، ”دا ماشوم واخله او زما دپاره سينه ورکوه او زۀ به تا له مزدورى درکوم.“ نو هغې ماشوم يوړو او هغۀ له يې سينه ورکوله.', NULL, '&nbsp;شهزادګۍ دې ښځې ته ووئيل، ”دا ماشوم واخله او زما دپاره سينه ورکوه او زۀ به تا له مزدورى درکوم.“ نو هغې ماشوم يوړو او هغۀ له يې سينه ورکوله.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1513, 'Exodus 2:10', 'Exodus', 2, 10, '&nbsp;کله چې دا ماشوم لږ لوئ شو نو هغې دا ماشوم د بادشاه لور له ورکړو او د بادشاه لور ماشوم خپل زوئ جوړ کړو. هغې د خپل ځان سره ووئيل، ”ما دا د اوبو نه راوچت کړے دے.“ نو موسىٰ نوم يې ورباندې کېښودو.', NULL, '&nbsp;کله چې دا ماشوم لږ لوئ شو نو هغې دا ماشوم د بادشاه لور له ورکړو او د بادشاه لور ماشوم خپل زوئ جوړ کړو. هغې د خپل ځان سره ووئيل، ”ما دا د اوبو نه راوچت کړے دے.“ نو موسىٰ نوم يې ورباندې کېښودو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1514, 'Exodus 2:11', 'Exodus', 2, 11, '&nbsp;چې کله موسىٰ لوئ شو نو هغه خپلو خلقو عبرانيانو له لاړو او هغۀ وليدل چې د هغوئ نه سخت کار اخستلے شو. هغۀ دا هم وليدل چې يو مِصرى يو عبرانے وهلو، دا د موسىٰ د خپلو خلقو نه يو کس وو.', NULL, '&nbsp;چې کله موسىٰ لوئ شو نو هغه خپلو خلقو عبرانيانو له لاړو او هغۀ وليدل چې د هغوئ نه سخت کار اخستلے شو. هغۀ دا هم وليدل چې يو مِصرى يو عبرانے وهلو، دا د موسىٰ د خپلو خلقو نه يو کس وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1515, 'Exodus 2:12', 'Exodus', 2, 12, '&nbsp;موسىٰ اخوا دېخوا وکتل او چې کله هغۀ ته پته ولګېده چې هيڅ څوک يې هم نۀ ګورى، نو هغه مِصرے يې ووژلو او د هغۀ لاش يې په شګو کښې پټ کړو.', NULL, '&nbsp;موسىٰ اخوا دېخوا وکتل او چې کله هغۀ ته پته ولګېده چې هيڅ څوک يې هم نۀ ګورى، نو هغه مِصرے يې ووژلو او د هغۀ لاش يې په شګو کښې پټ کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1516, 'Exodus 2:13', 'Exodus', 2, 13, '&nbsp;بله ورځ هغه بهر لاړو او وې ليدل چې دوه عبرانيان په خپلو کښې په جګړه وُو. هغۀ هغه يو ته وفرمائيل کوم چې په غلطه وو، ”تۀ ولې خپل عبرانے ورور وهې؟“', NULL, '&nbsp;بله ورځ هغه بهر لاړو او وې ليدل چې دوه عبرانيان په خپلو کښې په جګړه وُو. هغۀ هغه يو ته وفرمائيل کوم چې په غلطه وو، ”تۀ ولې خپل عبرانے ورور وهې؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1517, 'Exodus 2:14', 'Exodus', 2, 14, '&nbsp;هغه سړى ورته ووئيل، ”تۀ چا په مونږ مشر کړے يې او په مونږ يې قاضى جوړ کړے يې؟ تۀ ما هم وژنې څۀ لکه چې هغه مِصرے دې وژلے وو؟“ نو موسىٰ وويرېدو او د خپل ځان سره يې وفرمائيل، ”ښه نو لکه چې ما څۀ کړى دى د هغې خلقو ته پته لګېدلې ده.“', NULL, '&nbsp;هغه سړى ورته ووئيل، ”تۀ چا په مونږ مشر کړے يې او په مونږ يې قاضى جوړ کړے يې؟ تۀ ما هم وژنې څۀ لکه چې هغه مِصرے دې وژلے وو؟“ نو موسىٰ وويرېدو او د خپل ځان سره يې وفرمائيل، ”ښه نو لکه چې ما څۀ کړى دى د هغې خلقو ته پته لګېدلې ده.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1518, 'Exodus 2:17', 'Exodus', 2, 17, '&nbsp;خو څۀ شپانو د يترو لوڼه وشړلې. نو موسىٰ د هغوئ د بچ کولو دپاره ورَغلو او د هغوئ څاروو له يې اوبۀ ورکړې.', NULL, '&nbsp;خو څۀ شپانو د يترو لوڼه وشړلې. نو موسىٰ د هغوئ د بچ کولو دپاره ورَغلو او د هغوئ څاروو له يې اوبۀ ورکړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1519, 'Exodus 2:18', 'Exodus', 2, 18, '&nbsp;چې کله دوئ خپل پلار له راغلې، هغۀ ترې تپوس وکړو، ”تاسو ولې نن ډېر زر راغلئ؟“', NULL, '&nbsp;چې کله دوئ خپل پلار له راغلې، هغۀ ترې تپوس وکړو، ”تاسو ولې نن ډېر زر راغلئ؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1520, 'Exodus 2:19', 'Exodus', 2, 19, '&nbsp;هغوئ ورته ووئيل، ”يو مِصرى مونږ د شپانو نه بچ کړُو او هغۀ مونږ له اوبۀ هم راوخېژولې او زمونږ څاروو له يې ورکړې.“', NULL, '&nbsp;هغوئ ورته ووئيل، ”يو مِصرى مونږ د شپانو نه بچ کړُو او هغۀ مونږ له اوبۀ هم راوخېژولې او زمونږ څاروو له يې ورکړې.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1521, 'Exodus 2:20', 'Exodus', 2, 20, '&nbsp;هغۀ د خپلو لوڼو نه تپوس وکړو، ”هغه چرته دے؟ تاسو هغه سړے بهر ولې پرېښودو؟ لاړې شئ او هغه راوغواړئ چې مونږ سره روټۍ وخورى.“', NULL, '&nbsp;هغۀ د خپلو لوڼو نه تپوس وکړو، ”هغه چرته دے؟ تاسو هغه سړے بهر ولې پرېښودو؟ لاړې شئ او هغه راوغواړئ چې مونږ سره روټۍ وخورى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
(1522, 'Exodus 2:21', 'Exodus', 2, 21, '&nbsp;نو موسىٰ هلته اوسېدو ته راضى شو او يترو هغۀ ته خپله لور صفوره وادۀ کړه،', NULL, '&nbsp;نو موسىٰ هلته اوسېدو ته راضى شو او يترو هغۀ ته خپله لور صفوره وادۀ کړه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
