(1524, 'Exodus 2:23', 'Exodus', 2, 23, '&nbsp;ډېره موده پس چې د مِصر بادشاه مړ شو، خو بنى اِسرائيلو د غلامۍ په وجه فرياد کولو نو هغوئ په چغو وژړل، ”خُدايه پاکه، زمونږ مدد وکړه.“', NULL, '&nbsp;ډېره موده پس چې د مِصر بادشاه مړ شو، خو بنى اِسرائيلو د غلامۍ په وجه فرياد کولو نو هغوئ په چغو وژړل، ”خُدايه پاکه، زمونږ مدد وکړه.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
