(1823, 'Exodus 13:17', 'Exodus', 13, 17, '&nbsp;چې کله د مِصر فِرعون خلق تلو ته پرېښودل، نو خُدائ پاک دوئ په هغه لار بونۀ تلل کومه چې د درياب په غاړه د فلستيانو علاقې ته تلې وه، اګر چې دا لار لنډه وه. خُدائ پاک وفرمائيل، ”زۀ دا نۀ غواړم چې دا خلق پښېمانه شى او مِصر ته راواپس شى چې هغوئ ته دا پته ولګى چې په هغوئ جنګ راروان دے.“', NULL, '&nbsp;چې کله د مِصر فِرعون خلق تلو ته پرېښودل، نو خُدائ پاک دوئ په هغه لار بونۀ تلل کومه چې د درياب په غاړه د فلستيانو علاقې ته تلې وه، اګر چې دا لار لنډه وه. خُدائ پاک وفرمائيل، ”زۀ دا نۀ غواړم چې دا خلق پښېمانه شى او مِصر ته راواپس شى چې هغوئ ته دا پته ولګى چې په هغوئ جنګ راروان دے.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761756482, 1761756482),
